        Panel Card(string title,Label value,ProgressBar bar){var p=new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Margin=new Padding(0,0,9,0)};var caption=LabelAt(title,13,6,240,21);caption.ForeColor=Muted;caption.Font=new Font("Segoe UI",(float)(8)*global::UiScale.F);p.Controls.Add(caption);value.Location=new Point(13,29);value.Size=new Size(242,31);value.Text="—";value.Font=new Font("Segoe UI Semibold",(float)(title.StartsWith("COORD")?13:15)*global::UiScale.F);p.Controls.Add(value);if(bar!=null){bar.Location=new Point(15,66);bar.Size=new Size(220,6);bar.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Top;p.Controls.Add(bar);}return p;}
        void RefreshClients(){
            int chosen=clients.SelectedItem is ClientChoice?((ClientChoice)clients.SelectedItem).Pid:-1;clients.Items.Clear();int selected=-1,errors=0;
            foreach(var p in Process.GetProcessesByName("ElementClient")){try{using(var probe=new GameClient(p.Id,verified)){var s=probe.Read();int index=clients.Items.Add(new ClientChoice{Pid=p.Id,Label=s.ToString()});if(p.Id==chosen)selected=index;}}catch(Exception e){errors++;Log("PID "+p.Id+": "+e.Message);}finally{p.Dispose();}}
            if(clients.Items.Count>0)clients.SelectedIndex=selected>=0?selected:0;
            Status(clients.Items.Count+" personagem(ns) disponível(is)"+(errors>0?" · "+errors+" sem leitura":""));
        }
        void Connect(){
            if(recording)StopRecording("Gravação encerrada antes de trocar a conexão.");
            if(client!=null){execution.Stop();DropClient();snapshot=null;connect.Text="Conectar";connection.Text="Desconectado";connection.ForeColor=Muted;CloseTiles();ClearSnapshot();Log("Cliente desconectado.");return;}
            var selected=clients.SelectedItem as ClientChoice;if(selected==null){Status("Nenhum personagem disponível. Abra o cliente e clique Atualizar.");return;}
            lock(connected){if(connected.Contains(selected.Pid)){Status(selected+" já está conectado em outra conta do Mat Farm.");return;}connected.Add(selected.Pid);}claimedPid=selected.Pid;
            try{Log("Conectando ao processo");client=new GameClient(selected.Pid,verified);Log("Perfil do cliente conferido");snapshot=client.Read();Log("Personagem lido");connect.Text="Desconectar";connection.Text="Conectado · "+snapshot.Name;connection.ForeColor=RotaTheme.Good;UpdateSnapshot();Log("Preparando mapa");OpenTiles();Log("Mapa preparado");ReadResources();Log("Leitura conectada a "+snapshot.Name+" (PID "+snapshot.Pid+").");}
            catch(Exception e){DropClient();snapshot=null;ClearSnapshot();Error(e);}
        }
        void Poll(){
            if(farm!=null)farm.SetRunning(execution.Running);if(!execution.Running)farmCentered=false;
            if(!execution.Running)ReleaseCharacter();else if(Allowed!=null&&!Allowed()){execution.Stop();Status("Autorização do FarmZilla indisponível; rota parada.");}
            // Hidden (other menu) or minimized: no game reads for the screens; a running route has its own thread. Recording keeps sampling.
            var top=TopLevelControl as Form;bool hidden=!Visible||(top!=null&&top.WindowState==FormWindowState.Minimized);if(hidden&&!recording&&!trailRecording&&!execution.Running)return;
            executeRoute.Enabled=client!=null&&!execution.Running;stopRoute.Enabled=execution.Running;if(client==null)return;
            try{snapshot=client.Read();UpdateSnapshot();UpdateActivity();TrailSample();if((DateTime.Now-lastResources).TotalMilliseconds>=1000)ReadResources();if(recording){if(route.Character!=snapshot.Name){StopRecording("O personagem mudou; gravação interrompida.");return;}var point=Waypoint.From(snapshot);if(route.Points.Count==0||route.Points[route.Points.Count-1].DistanceTo(point)>=(double)spacing.Value)Append(point);}if(++refreshCount%15==0)UpdateSummary();}
            catch(Exception e){execution.Stop();StopRecording("Leitura indisponível; gravação interrompida.");DropClient();snapshot=null;connect.Text="Conectar";connection.Text="Leitura interrompida";connection.ForeColor=Rubi.Accent;ClearSnapshot();Log(e.Message);Status("Conexão perdida. Atualize a lista e reconecte.");}
        }
        void UpdateSnapshot(){if(snapshot==null)return;playerText.Text=snapshot.Name+" · Nv. "+snapshot.Level;hpText.Text=snapshot.Hp.ToString("N0")+" / "+snapshot.MaxHp.ToString("N0");mpText.Text=snapshot.Mp.ToString("N0")+" / "+snapshot.MaxMp.ToString("N0");hpBar.Value=(int)Math.Min(100,100.0*snapshot.Hp/Math.Max(1,snapshot.MaxHp));mpBar.Value=(int)Math.Min(100,100.0*snapshot.Mp/Math.Max(1,snapshot.MaxMp));hpBar.Invalidate();mpBar.Invalidate();positionText.Text=String.Format("{0:F1}, {1:F1} ↑ {2:F1}",snapshot.MapX,snapshot.MapZ,snapshot.MapHeight);tips.SetToolTip(positionText,String.Format("Coordenadas internas: X {0:F3} · Y {1:F3} · Z {2:F3}",snapshot.X,snapshot.Y,snapshot.Z));map.Player=routePreview.Player=farm.Map.Player=snapshot;if(Math.Abs(snapshot.X-drawnX)>0.05||Math.Abs(snapshot.Z-drawnZ)>0.05||Double.IsNaN(drawnX)){drawnX=snapshot.X;drawnZ=snapshot.Z;map.Invalidate();routePreview.Invalidate();farm.Map.Invalidate();SyncOverlay();}}
        void ClearSnapshot(){activityText.Text="Sem leitura";inventory=null;inventorySignature="";inventoryList.Items.Clear();flightText.Text="Sem leitura";playerText.Text=hpText.Text=mpText.Text=positionText.Text="—";hpBar.Value=mpBar.Value=0;hpBar.Invalidate();mpBar.Invalidate();map.Player=routePreview.Player=farm.Map.Player=null;drawnX=drawnZ=double.NaN;map.Terrain=routePreview.Terrain=null;routePreview.Resources.Clear();worldPanel.UpdateFrame(null,null,"");map.Invalidate();routePreview.Invalidate();}
        bool HaveSnapshot(){if(client==null||snapshot==null||(DateTime.Now-snapshot.ReadAt).TotalSeconds>2){Status("Conecte a um personagem antes de capturar sua posição.");return false;}return true;}
        void AddResourceWaypoint(ResourceMarker resource){if(!HaveSnapshot()||!EnsureRouteCharacter())return;if(!route.ResourceIds.Contains(resource.TemplateId)){route.ResourceIds.Add(resource.TemplateId);worldPanel.SelectionChanged();}Append(new Waypoint{X=resource.X,Y=resource.Y,Z=resource.Z,Action="Coletar",ResourceId=resource.TemplateId,ItemId=resource.ItemId});Status("Ponto "+points.Count+" adicionado: "+resource.Name+". Ordem definida pelos cliques.");}
        void AddCurrent(){if(!HaveSnapshot())return;if(!EnsureRouteCharacter())return;Append(Waypoint.From(snapshot));Status("Ponto "+points.Count+" capturado de "+snapshot.Name+".");}
        bool EnsureRouteCharacter(){if(route.Points.Count>0&&!String.IsNullOrEmpty(route.Character)&&route.Character!=snapshot.Name){Status("Esta rota está associada a "+route.Character+". Crie uma nova para gravar outro personagem.");return false;}route.Character=snapshot.Name;return true;}
        void Append(Waypoint p){if(points.Count>=20000){StopRecording("Limite de 20 mil pontos atingido.");return;}changingGrid=true;try{points.Add(p);}finally{changingGrid=false;}SetDirty();UpdateSummary();if(grid.Rows.Count>0)grid.FirstDisplayedScrollingRowIndex=grid.Rows.Count-1;}
        void ToggleRecording(){if(recording){StopRecording("Gravação finalizada.");return;}if(!HaveSnapshot()||!EnsureRouteCharacter()||!grid.EndEdit())return;recording=true;record.Text="Parar gravação";record.BackColor=Rubi.Shade(Rubi.Accent,-75);if(points.Count==0||points[points.Count-1].DistanceTo(Waypoint.From(snapshot))>=1)Append(Waypoint.From(snapshot));Log("Gravação iniciada. Mova o personagem manualmente no jogo.");Status("Gravando trajeto de "+snapshot.Name+" · distância mínima "+spacing.Value+".");}
        void StopRecording(string text){if(!recording)return;recording=false;record.Text="Gravar trajeto";record.BackColor=Rubi.Field;Log(text);Status(text);}
        void Bind(){loading=true;try{points=new BindingList<Waypoint>(route.Points);grid.DataSource=points;routeName.Text=route.Name;loop.Checked=route.Loop;flightHeight.Value=(decimal)Math.Max(10,Math.Min(300,route.FlightHeight));map.Route=routePreview.Route=route;}finally{loading=false;}worldPanel.SetSearchSettings(route.Region,route.SearchRadius);worldPanel.SelectionChanged();UpdateSummary();}
        void StartRoute(){if(!HaveSnapshot()||execution.Running)return;try{if(!grid.EndEdit())return;StopRecording("Gravação encerrada.");if(!RotaAllowed())return;execution.StartAttack=StartAttack;execution.AttackRunning=AttackRunning;execution.ReviveInTown=ReviveInTown;execution.Start(client.Pid,route,catalog,RotaPaths.Bridge());LockCharacter();Log("Log: "+execution.LogPath);executeRoute.Enabled=false;stopRoute.Enabled=true;}catch(Exception e){Error(e);}}
        void StartSurvey(RectangleF bounds){StartSurvey(bounds,600);}
        // "Escanear raio": sweep the whole radius around the character (up to the world), saving every material found.
        void StartSurvey(RectangleF bounds,int maxPoints){if(!HaveSnapshot()||execution.Running)return;try{var current=client.Read();if(!current.FlightStateKnown||!current.IsFlying)throw new InvalidOperationException("Ative o voo antes de mapear a região.");var survey=RegionSurvey.Plan(bounds,current,maxPoints);survey.FlightHeight=farm.Height;StopRecording("Gravação encerrada para mapear.");if(!RotaAllowed())return;execution.StartAttack=StartAttack;execution.AttackRunning=AttackRunning;execution.ReviveInTown=ReviveInTown;execution.Start(client.Pid,survey,catalog,RotaPaths.Bridge());LockCharacter();double hours=survey.Points.Count*120/12.0/3600;Log("Mapeando área: "+survey.Points.Count+" destinos (cerca de "+(hours<1?Math.Ceiling(hours*60)+" min":hours.ToString("F1")+" h")+" de voo, na altura atual); todos os tipos encontrados serão registrados. A rota de coleta foi preservada. Log: "+execution.LogPath);Status("Mapeamento em andamento. Use Parar para interromper; materiais aparecem conforme são carregados.");}catch(Exception error){Error(error);}}
        bool RotaAllowed(){if(Allowed==null||Allowed())return true;Status("FarmZilla sem autorização no momento; a rota não foi iniciada.");return false;}
        void LockCharacter(){lockedPid=client.Pid;lockedName=snapshot.Name;RotaLock.Set(lockedPid,lockedName);string text=lockedName+" em rota: seguir, ataque, teleporte, buff e missões do FarmZilla deixam esse personagem de lado até a rota parar.";Log(text,Notify==null);if(Notify!=null)Notify("Rota: "+text);}
        // While the route thread is still finishing a native call, the lock is kept until it really stops.
        void ReleaseCharacter(){if(lockedPid==0)return;int pid=lockedPid;string name=lockedName;lockedPid=0;
            if(execution.Running){var running=execution;Task.Run(async()=>{for(int i=0;i<100&&running.Running;i++)await Task.Delay(100);RotaLock.Clear(pid);});return;}
            RotaLock.Clear(pid);string text=name+" saiu da rota e voltou para o FarmZilla.";Log(text,Notify==null);if(Notify!=null)Notify("Rota: "+text);}
        // FarmZilla closing: no dialog may hold its shutdown, so unsaved edits go to a separate file in the rotas folder.
        void AutoSave(){if(!dirty||route.Points.Count==0)return;try{string path=Path.Combine(RotaPaths.Routes,"rota-nao-salva-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json");route.Save(path);dirty=false;Log("Alterações não salvas guardadas em "+path);}catch(Exception error){Log("Rota não salva: "+error.Message);}}
        public async Task CloseForOwner(){ownerClosing=true;if(overlay!=null&&!overlay.IsDisposed)overlay.Dispose();execution.Stop();for(int i=0;i<60&&execution.Running;i++)await Task.Delay(100);if(IsDisposed)return;if(TopLevel){Close();return;}OnFormClosingRequest(this,new FormClosingEventArgs(CloseReason.FormOwnerClosing,false));Dispose();}
        // Inside FarmZilla's window (side menu "Rota"): no title, no own header, fills the host panel.
        public void Embed(Control host){embedded=true;TopLevel=false;FormBorderStyle=FormBorderStyle.None;MinimumSize=Size.Empty;Dock=DockStyle.Fill;headerPanel.Visible=false;rootLayout.RowStyles[0].Height=0;rootLayout.Padding=new Padding(12,4,12,4);host.Controls.Add(this);Visible=false;}
        string ChoicesFile{get{return Path.Combine(RotaPaths.Data,SlotFile("escolhas_materiais.txt"));}}
        void SaveChoices(){try{File.WriteAllText(ChoicesFile,String.Join(",",route.ResourceIds));}catch(Exception error){Log("Escolhas: "+error.Message,false);}}
        void LoadChoices(){if(route.ResourceIds.Count>0)return;try{if(!File.Exists(ChoicesFile))return;foreach(var part in File.ReadAllText(ChoicesFile).Split(',')){int id;if(Int32.TryParse(part.Trim(),out id)&&catalog.Definitions.ContainsKey(id)&&!route.ResourceIds.Contains(id))route.ResourceIds.Add(id);}}catch{}}
        // Farm tab: choose materials (shared with the route's choices, saved), start/stop, scan around the character.
        void WireFarm(){farm.Map.IconFor=worldPanel.MapIcon;farm.Height=LoadHeight();
            farm.MaterialToggled+=(id,chosen)=>{if(route.ResourceIds.Contains(id)==chosen)return;if(chosen)route.ResourceIds.Add(id);else route.ResourceIds.Remove(id);SetDirty();UpdateSummary();SaveChoices();worldPanel.SelectionChanged();UpdateFarm(lastObserved);};
            farm.StartRequested+=StartFarm;farm.OverlayRequested+=ToggleOverlay;farm.SaveRouteRequested+=SaveFarmRoute;farm.LoadRouteRequested+=LoadFarmRoute;LoadExcluded();farm.Radius=StartRadius;
            // A click on a point of the Farm map takes it out of the route (saved); "Restaurar pontos" brings them back.
            farm.Map.ResourceClicked+=r=>{excludedPoints.Add(FarmPlanner.Key(r.TemplateId,r.X,r.Z));SaveExcluded();Replan();Status(r.Name+": ponto tirado da rota do farm.");};
            farm.RestoreRequested+=()=>{excludedPoints.Clear();SaveExcluded();Replan();Status("Pontos tirados voltaram para a rota do farm.");};
            farm.PlanSettingsChanged+=()=>{SaveRadius(farm.Radius);Replan();UpdateFences();farm.Map.FitRadius(farm.Radius);};
            farm.ScanRadiusChanged+=()=>{UpdateFences();farm.Map.FitRadius(farm.ScanRadius);};farm.StopRequested+=()=>{execution.Stop();Log("Parada solicitada; o movimento já enviado pode terminar no jogo.");};
            farm.ScanRequested+=r=>{if(!HaveSnapshot())return;var s=snapshot;StartSurvey(RectangleF.FromLTRB((float)(s.X-r),(float)(s.Z-r),(float)(s.X+r),(float)(s.Z+r)),8000);};WireTrail();}
        string HeightFile{get{return Path.Combine(RotaPaths.Data,SlotFile("altura_voo.txt"));}}
        void SaveHeight(double value){try{File.WriteAllText(HeightFile,((int)value).ToString());}catch{}}
        double LoadHeight(){try{int v;if(File.Exists(HeightFile)&&Int32.TryParse(File.ReadAllText(HeightFile).Trim(),out v)&&v>=10&&v<=300)return v;}catch{}return 60;}
        void UpdateFarm(List<ResourceMarker> observed){if(farm==null||observed==null)return;var chosen=new HashSet<int>(route.ResourceIds);
            farm.Map.Resources=observed.Where(r=>(chosen.Contains(r.TemplateId)||!r.Historical)&&!excludedPoints.Contains(FarmPlanner.Key(r.TemplateId,r.X,r.Z))).ToList();farm.Map.Invalidate();
            var groups=observed.Where(r=>catalog.Ground(r.TemplateId)).GroupBy(r=>r.TemplateId).ToDictionary(g=>g.Key,g=>g.ToList());var items=new List<FarmMaterial>();ResourceDefinition d;
            foreach(var kv in groups)if(catalog.Definitions.TryGetValue(kv.Key,out d))items.Add(new FarmMaterial{Id=kv.Key,Name=catalog.FarmName(kv.Key),Source=catalog.MaterialName(kv.Key),Points=kv.Value.Count,Loaded=kv.Value.Count(r=>!r.Historical)});
            foreach(var id in chosen)if(!groups.ContainsKey(id)&&catalog.Definitions.TryGetValue(id,out d))items.Add(new FarmMaterial{Id=id,Name=catalog.FarmName(id),Source=catalog.MaterialName(id)});
            if(catalogMaterials==null)catalogMaterials=catalog.Definitions.Values.Where(def=>catalog.Ground(def.id)).Select(def=>new FarmMaterial{Id=def.id,Name=catalog.FarmName(def.id),Source=catalog.MaterialName(def.id)}).ToList();
            foreach(var m in catalogMaterials)if(!groups.ContainsKey(m.Id)&&!chosen.Contains(m.Id))items.Add(m);
            farm.SetMaterials(items,chosen);if(!execution.Running&&snapshot!=null)BuildFarmPlan();UpdateFences();SyncOverlay();}
        // Every collectible of the catalog (0.43.0), built once and shown with 0 points until scanned.
        static List<FarmMaterial> catalogMaterials;
        // Mirrors the Farm map into the always-on-top overlay (same tiles, plan, materials and fences).
        void SyncOverlay(){if(overlay==null||overlay.IsDisposed||!overlay.Visible||farm==null)return;var m=overlay.Map;var f=farm.Map;m.Tiles=f.Tiles;m.Terrain=f.Terrain;m.Player=f.Player;m.Route=f.Route;m.Resources=f.Resources;m.IconFor=f.IconFor;m.Fences.Clear();m.Fences.AddRange(f.Fences);m.Invalidate();overlay.SetStatus(farm.Summary);}
        void ToggleOverlay(){if(overlay==null||overlay.IsDisposed){overlay=new FarmOverlay();var area=Screen.PrimaryScreen.WorkingArea;overlay.Location=new Point(area.Right-overlay.Width-12,area.Top+12);}
            if(overlay.Visible)overlay.Hide();else{overlay.Show();SyncOverlay();}}
        // Farm radius (rubi, around where the farm started) and scan radius (blue, around the character) as fences on the map.
        void UpdateFences(){if(farm==null)return;farm.Map.Fences.Clear();if(snapshot==null){farm.Map.Invalidate();return;}
            farm.Map.Fences.Add(Tuple.Create(farmCentered?farmCenterX:(double)snapshot.X,farmCentered?farmCenterZ:(double)snapshot.Z,farm.Radius,Rubi.Accent,"Farm"));
            farm.Map.Invalidate();}
        // Loaded .txt route (0.42.0): while loaded, it is the farm plan (shown, started and repeated) instead of the automatic one.
        FarmRouteText loadedRoute;
        RouteDocument BuildFarmPlan(){if(loadedRoute!=null){var fixedPlan=loadedRoute.ToPlan();farm.SetPlan(fixedPlan);return fixedPlan;}var plan=farmCentered?FarmPlanner.Build(lastObserved,new HashSet<int>(route.ResourceIds),snapshot,farm.Radius,excludedPoints,farmCenterX,farmCenterZ):FarmPlanner.Build(lastObserved,new HashSet<int>(route.ResourceIds),snapshot,farm.Radius,excludedPoints);farm.SetPlan(plan);return plan;}
        string ExcludedFile{get{return Path.Combine(RotaPaths.Data,SlotFile("pontos_excluidos.txt"));}}
        void SaveExcluded(){try{File.WriteAllLines(ExcludedFile,excludedPoints.ToArray());}catch{}farm.SetExcludedCount(excludedPoints.Count);}
        void LoadExcluded(){try{if(File.Exists(ExcludedFile))foreach(var line in File.ReadAllLines(ExcludedFile))if(line.Trim().Length>0)excludedPoints.Add(line.Trim());}catch{}farm.SetExcludedCount(excludedPoints.Count);}
        void Replan(){UpdateFarm(lastObserved);if(snapshot!=null)BuildFarmPlan();}
        // Fixed sequence (0.34.0, owner): the numbered plan made when the farm starts is repeated lap after lap in the same
        // order; removed points or unchecked materials drop out; an empty plan is rebuilt (e.g. after a scan).
        RouteDocument FixedPlan(){if(farmFixed==null||farmFixed.Points.Count==0)farmFixed=BuildFarmPlan();
            var plan=new RouteDocument{Name=farmFixed.Name,Character=farmFixed.Character,Loop=false,ResourceIds=route.ResourceIds.ToList()};
            foreach(var point in farmFixed.Points)if(route.ResourceIds.Contains(point.ResourceId)&&!excludedPoints.Contains(FarmPlanner.Key(point.ResourceId,point.X,point.Z)))plan.Points.Add(point);
            if(plan.Points.Count==0){farmFixed=BuildFarmPlan();return farmFixed;}
            farm.SetPlan(plan);return plan;}
        void SaveFarmRoute(){RouteDocument plan;if(loadedRoute!=null)plan=loadedRoute.ToPlan();else if(execution.Running&&farmFixed!=null)plan=farmFixed;else if(snapshot!=null)plan=BuildFarmPlan();else{Status("Conecte o personagem para montar a rota antes de salvar.");return;}
            if(plan==null||plan.Points.Count==0){Status("Rota vazia: marque materiais e escaneie antes de salvar.");return;}
            string who=snapshot!=null?snapshot.Name:"rota";using(var dialog=new SaveFileDialog{Filter="Rota do Mat Farm (*.txt)|*.txt",DefaultExt="txt",AddExtension=true,FileName=(loadedRoute!=null?loadedRoute.Name:who+"-matfarm")+".txt",Title="Salvar rota do Mat Farm",InitialDirectory=RotaPaths.Routes}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;
            try{var file=new FarmRouteText{Name=Path.GetFileNameWithoutExtension(dialog.FileName),Character=who,Height=farm.Height,Radius=farm.Radius,Materials=route.ResourceIds.ToList(),Points=plan.Points.ToList()};file.Write(dialog.FileName);Status("Rota salva: "+Path.GetFileName(dialog.FileName)+" ("+file.Points.Count+" pontos).");Log("Rota do Mat Farm salva em "+dialog.FileName);}catch(Exception e){Error(e);}}}
        void LoadFarmRoute(){if(execution.Running){Status("Pare o farm antes de trocar a rota.");return;}
            if(loadedRoute!=null){loadedRoute=null;farm.SetLoadedRoute(null,0);farmFixed=null;Replan();Status("Rota carregada retirada; o farm volta a montar o plano pelos materiais marcados.");return;}
            using(var dialog=new OpenFileDialog{Filter="Rota do Mat Farm (*.txt)|*.txt|Todos os arquivos (*.*)|*.*",Title="Carregar rota do Mat Farm",InitialDirectory=RotaPaths.Routes}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;
            if(TrailRoute.IsTrail(dialog.FileName)){Status("Esse arquivo é um trajeto manual: abra em Manual > Carregar trajeto.");return;}
            try{var file=FarmRouteText.Read(dialog.FileName);route.ResourceIds.Clear();route.ResourceIds.AddRange(file.Materials);SaveChoices();farm.Height=file.Height;loadedRoute=file;farmFixed=null;farm.Radius=file.Radius;SaveRadius(file.Radius);farm.SetLoadedRoute(file.Name,file.Points.Count);Replan();farm.SetPlan(file.ToPlan());worldPanel.SelectionChanged();
                Status("Rota carregada: "+file.Name+" · "+file.Points.Count+" pontos"+(file.Character.Length>0&&snapshot!=null&&file.Character!=snapshot.Name?" (salva por "+file.Character+")":"")+". Clique Iniciar farm.");Log("Rota do Mat Farm carregada de "+dialog.FileName);}catch(Exception e){Error(e);}}}
        string RadiusFile{get{return Path.Combine(RotaPaths.Data,SlotFile("raio_farm.txt"));}}
        void SaveRadius(double value){try{File.WriteAllText(RadiusFile,((int)value).ToString());}catch{}}
        // 0.47.2 (owner): the automatic farm always opens with a 900 radius; more only if the user raises it.
        const double StartRadius=900;
        double LoadRadius(){try{int v;if(File.Exists(RadiusFile)&&Int32.TryParse(File.ReadAllText(RadiusFile).Trim(),out v)&&v>=100&&v<=30000)return v;}catch{}return 1500;}
        void StartFarm(){if(!HaveSnapshot()||execution.Running)return;farmCentered=true;farmCenterX=snapshot.X;farmCenterZ=snapshot.Z;if(route.ResourceIds.Count==0){Status("Marque pelo menos um material na lista.");return;}
            try{StopRecording("Gravação encerrada para o farm.");if(!RotaAllowed())return;var first=BuildFarmPlan();farmFixed=first;if(first.Points.Count==0)Status("Nenhum ponto conhecido dos materiais marcados: use Escanear arredores. O farm espera e tenta de novo.");
                execution.StartAttack=StartAttack;execution.AttackRunning=AttackRunning;execution.ReviveInTown=ReviveInTown;
                execution.StartFarm(client.Pid,catalog,RotaPaths.Bridge(),()=>{if(IsDisposed)return null;try{return (RouteDocument)Invoke(new Func<RouteDocument>(FixedPlan));}catch{return null;}},farm.Height);SaveHeight(farm.Height);
                LockCharacter();farm.SetRunning(true);Log("Farm iniciado com "+first.Points.Count+" pontos conhecidos. Log: "+execution.LogPath);}
            catch(Exception e){Error(e);}}
        public void ReportUiError(Exception error){execution.Stop();Log("Erro de interface: "+error.Message);Status("Falha registrada em logs/interface-erros.txt.");}
        void UpdateSummary(){routeSummary.Text=route.Points.Count+" pontos  ·  "+route.Length().ToString("F1")+" unidades  ·  "+(route.Loop?"Circular":"Ida")+"  ·  "+(String.IsNullOrEmpty(route.Character)?"Sem personagem":route.Character)+"  ·  "+route.ResourceIds.Count+" materiais escolhidos · Clique nos marcadores para ordenar";map.Invalidate();routePreview.Invalidate();}
        void OpenTiles(){CloseTiles();try{mapTiles=new MapTiles(client.GameDirectory);worldPanel.SetAssets(mapTiles);routePreview.Tiles=farm.Map.Tiles=mapTiles;farm.ResetIcons();}catch(Exception e){Log("Mapa: "+e.Message);}}
        void CloseTiles(){worldPanel.SetAssets(null);routePreview.Tiles=farm.Map.Tiles=null;if(mapTiles!=null){mapTiles.Dispose();mapTiles=null;}}
        void ReadResources(){lastResources=DateTime.Now;try{var frame=client.ReadResources(catalog,snapshot);TrailSeen(frame);var observed=MaterialMap.Merge(history.Merge(snapshot,frame),catalog,snapshot,frame);worldPanel.UpdateFrame(snapshot,frame,"",observed);routePreview.Terrain=farm.Map.Terrain=frame.Terrain;lastObserved=observed;UpdateFarm(observed);routePreview.Resources=observed.Where(r=>route.ResourceIds.Contains(r.TemplateId)||history.Collectible(r.TemplateId)).ToList();routePreview.Invalidate();resourceError="";ReadInventory(frame);}catch(Exception e){execution.Stop();worldPanel.UpdateFrame(snapshot,null,e.Message);routePreview.Resources.Clear();routePreview.Terrain=null;routePreview.Invalidate();if(e.Message!=resourceError){Log("Recursos: "+e.Message);resourceError=e.Message;}}}
        void ReadInventory(ResourceFrame frame){
            flightText.Text=(snapshot.FlightStateKnown?(snapshot.IsFlying?"Voando":"Voo desligado"):"Voo: estado transitório")+" · altura atual "+snapshot.MapHeight.ToString("F1");
            try{inventory=client.ReadInventory();string signature=String.Join(";",inventory.Items.Select(i=>i.Slot+":"+i.Id+":"+i.Quantity));if(signature!=inventorySignature){inventorySignature=signature;inventoryList.BeginUpdate();try{inventoryList.Items.Clear();foreach(var item in inventory.Items){var row=new ListViewItem((item.Slot+1).ToString());row.SubItems.Add(item.Id.ToString());row.SubItems.Add(item.Quantity.ToString());row.SubItems.Add(VerifiedRewards.ItemName(item.Id));inventoryList.Items.Add(row);}}finally{inventoryList.EndUpdate();}}}catch(Exception e){inventory=null;inventorySignature="";inventoryList.Items.Clear();flightText.Text+=" · Inventário indisponível: "+e.Message;}
        }
        void UpdateActivity(){try{var activity=client.ReadActivity();string text;switch(activity.Kind){case ActivityKind.Approaching:text="Aproximando do alvo";break;case ActivityKind.Collecting:var action=activity.Actions.First(a=>a.Kind==ActivityKind.Collecting);ResourceDefinition definition;text=catalog.Definitions.TryGetValue(action.ResourceId,out definition)?"Cavando: "+definition.nome:"Coletando · ID "+action.ResourceId;break;case ActivityKind.Moving:text="Em movimento";break;case ActivityKind.FlightTransition:text="Transição de voo";break;case ActivityKind.Idle:text="Sem aproximação/coleta ativa";break;default:text="Outra ação do personagem";break;}activityText.Text=text;}catch{activityText.Text="Ação indisponível; aguardando nova leitura";}}
        void SetDirty(){dirty=true;Text="FarmZilla · Rota · "+route.Name+" *";}
        int SelectedIndex(){return grid.CurrentRow==null?-1:grid.CurrentRow.Index;}
        void MovePoint(int delta){if(recording){Status("Pare a gravação para reorganizar pontos.");return;}if(!grid.EndEdit())return;int at=SelectedIndex(),to=at+delta;if(at<0||to<0||to>=points.Count)return;var p=points[at];changingGrid=true;try{points.RemoveAt(at);points.Insert(to,p);grid.CurrentCell=grid.Rows[to].Cells[0];}finally{changingGrid=false;}SetDirty();UpdateSummary();}
        void RemovePoint(){if(recording){Status("Pare a gravação para remover pontos.");return;}int at=SelectedIndex();if(at<0)return;points.RemoveAt(at);SetDirty();UpdateSummary();}
        void ValidateCell(object sender,DataGridViewCellValidatingEventArgs e){if(e.RowIndex<0)return;string name=grid.Columns[e.ColumnIndex].DataPropertyName;if(name=="X"||name=="Y"||name=="Z"){double v;if(!Double.TryParse(Convert.ToString(e.FormattedValue),out v)||!GameClient.ValidCoordinate(v)){e.Cancel=true;Status("Coordenada inválida.");}}else if(name=="WaitMs"){int v;if(!Int32.TryParse(Convert.ToString(e.FormattedValue),out v)||v<0||v>3600000){e.Cancel=true;Status("A espera deve estar entre 0 e 3.600.000 ms.");}}}
        bool DiscardOrSave(){if(!dirty)return true;var answer=MessageBox.Show(this,"Salvar as alterações desta rota?","FarmZilla · Rota",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.Cancel)return false;if(answer==DialogResult.Yes)return SaveRoute(false);return true;}
        void NewRoute(){if(!DiscardOrSave())return;StopRecording("Gravação encerrada.");route=new RouteDocument();currentFile=null;dirty=false;LoadChoices();Bind();Text="FarmZilla · Rota";Status("Nova rota criada.");}
        void OpenRoute(){if(!DiscardOrSave())return;using(var dialog=new OpenFileDialog{Filter="Rotas JSON (*.json)|*.json",Title="Abrir rota",InitialDirectory=RotaPaths.Routes}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{var loaded=RouteDocument.Load(dialog.FileName);StopRecording("Gravação encerrada.");route=loaded;currentFile=dialog.FileName;dirty=false;Bind();Text="FarmZilla · Rota · "+route.Name;Log("Rota carregada: "+Path.GetFileName(currentFile));}catch(Exception e){Error(e);}}}
        bool SaveRoute(bool saveAs){if(!grid.EndEdit())return false;string path=currentFile;if(saveAs||String.IsNullOrEmpty(path)){using(var dialog=new SaveFileDialog{Filter="Rotas JSON (*.json)|*.json",DefaultExt="json",AddExtension=true,FileName="rota.json",Title="Salvar rota",InitialDirectory=RotaPaths.Routes}){if(dialog.ShowDialog(this)!=DialogResult.OK)return false;path=dialog.FileName;}}try{route.Save(path);currentFile=path;dirty=false;Text="FarmZilla · Rota · "+route.Name;Log("Rota salva: "+Path.GetFileName(path));Status("Rota salva com "+points.Count+" pontos.");return true;}catch(Exception e){Error(e);return false;}}
        void Error(Exception e){Log(e.Message);Status(e.Message);MessageBox.Show(this,e.Message,"FarmZilla · Rota",MessageBoxButtons.OK,MessageBoxIcon.Information);}
        void Status(string text){status.Text=text;}
        void Log(string text){Log(text,true);}
        // remote: also into FarmZilla's registro (/admin > Registro); false when Notify already wrote it there.
        void Log(string text,bool remote){if(remote)DiagnosticLog.Write("Rota: "+text);try{File.AppendAllText(Path.Combine(RotaPaths.Logs,"aplicativo.log"),DateTime.Now.ToString("o")+"  "+text+Environment.NewLine);}catch{}if(logBox.TextLength>35000)logBox.Clear();logBox.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);}
        void OnFormClosingRequest(object sender,FormClosingEventArgs e){timer.Stop();StopRecording("Gravação encerrada.");StopTrailRecording("Gravação do trajeto encerrada.");if(ownerClosing||e.CloseReason!=CloseReason.UserClosing)AutoSave();else if(!DiscardOrSave()){e.Cancel=true;timer.Start();return;}execution.Stop();ReleaseCharacter();try{history.Save();}catch(Exception error){Log("Histórico: "+error.Message);}CloseTiles();if(client!=null)DropClient();timer.Dispose();tips.Dispose();}
    }
}






